def count_pentagons_original_logic(n):
    K = n - (n-1)//2
    count = 0
    for d1 in range(1, n):
        for d2 in range(1, n - d1):
            for d3 in range(1, n - d1 - d2):
                rem = n - d1 - d2 - d3
                if rem < 2: continue
                s1 = d1 + d2
                s2 = d2 + d3
                s4 = rem
                s1_ok = 1 if s1 >= K else 0
                s2_ok = 1 if s2 >= K else 0
                s4_ok = 1 if s4 >= K else 0
                base_ok = s1_ok + s2_ok + s4_ok
                for d4 in range(1, rem):
                    s3 = d3 + d4
                    s5 = rem - d4 + d1
                    if (base_ok + (1 if s3 >= K else 0) + (1 if s5 >= K else 0)) == 2:
                        count += 1
    return count

