def count_pentagons_brute(n):
    count = 0
    vertices = list(range(n))
    for combo in itertools.combinations(vertices, 5):
        d = []
        for i in range(5):
            d.append(combo[i+1] - combo[i] if i < 4 else n - (combo[4] - combo[0]))
        K = n - (n-1)//2
        s = []
        for i in range(5):
            s.append(d[i] + d[(i+1)%5])
        acute_angles = sum(1 for val in s if val >= K)
        if acute_angles == 2:
            count += 1
    return count

